var GTOPICS = typeof GTOPICS==='undefined' ? [] : GTOPICS;
GTOPICS.push(
 { id:"T25", title:"Sifət və zərf", level:"A2",
   intro:"Bu dərsdə sifəti (necə? hansı? — big, happy) və zərfi (necə edir? — slowly, well) ayırmağı öyrənəcəksən. Sonra too / enough və bored / boring fərqini görəcəksən.",
   steps:[
     { h:"Sifət: əşyanı və adamı təsvir edir",
       t:["Sifət isimi təsvir edir: big, small, happy, old, beautiful. Sualı: necə? hansı? Azərbaycanca kimi, sifət isimdən ƏVVƏL gəlir: a big house (böyük ev).",
          "Sifət be felindən (am / is / are / was / were) sonra da gəlir: The house is big. Sifət heç vaxt dəyişmir: cəmdə də -s almır. two big houses deyirik, two bigs houses yox."],
       tbl:[["sifət + isim","a new car"],["be + sifət","The car is new."]],
       ex:[["She has a small dog.","Onun kiçik iti var."],["The weather is nice today.","Bu gün hava gözəldir."],["They are happy.","Onlar xoşbəxtdirlər."],["We live in an old flat.","Köhnə mənzildə yaşayırıq."]],
       no:"a house big / reds cars — səhvdir (sifət isimdən əvvəl gəlir və -s almır)",
       q:[ {t:"mc", q:"I have a ___ .", opts:["new phone","phone new","news phone"], hint:"Sifət isimdən əvvəl gəlir: new phone."},
           {t:"mc", q:"These are ___ apples.", opts:["red","reds","redly"], hint:"Sifət cəmdə -s almır."},
           {t:"mc", q:"My brother is ___ .", opts:["tall","tally","talls"], hint:"is-dən sonra sifət gəlir: tall."},
           {t:"gap", q:"It is a ___ (big) city.", a:["big"], hint:"Sifət dəyişmir: big."},
           {t:"gap", q:"They have two ___ (small) children.", a:["small"], hint:"Cəmdə də sifət eyni qalır: small."} ] },

     { h:"Zərf: hərəkəti təsvir edir (-ly)",
       t:["Zərf feli təsvir edir: hərəkət NECƏ edilir? Çox vaxt sifətə -ly əlavə edirik: slow → slowly, quiet → quietly, careful → carefully. Zərf adətən feldən və ya obyektdən SONRA gəlir: He drives slowly.",
          "Yazılış: sifət samit + y ilə bitirsə, y → i olur: easy → easily, happy → happily. Üç istisnanı əzbərlə: good → well (yaxşı), fast → fast, hard → hard (-ly almır)."],
       tbl:[["sifət","zərf"],["slow","slowly"],["easy","easily"],["good","well"],["fast / hard","fast / hard"]],
       ex:[["He speaks quietly.","O, sakit danışır."],["She is a good singer. She sings well.","O, yaxşı müğənnidir. Yaxşı oxuyur."],["Please drive carefully.","Zəhmət olmasa, ehtiyatla sür."],["I can do it easily.","Bunu asanlıqla edə bilərəm."]],
       no:"He drives slow. / She sings good. — səhvdir (feli zərf təsvir edir: slowly, well)",
       q:[ {t:"mc", q:"He walks ___ .", opts:["slowly","slow","slowy"], hint:"Hərəkət necə? → zərf: slowly."},
           {t:"mc", q:"She speaks English very ___ .", opts:["well","good","goodly"], hint:"good-un zərfi well-dir."},
           {t:"mc", q:"He is a ___ driver.", opts:["careful","carefully","carefuly"], hint:"driver isimdir, onu sifət təsvir edir: careful."},
           {t:"gap", q:"The children played ___ (happy).", a:["happily"], hint:"happy → happily (y → i + ly)."},
           {t:"gap", q:"She runs very ___ (fast).", a:["fast"], hint:"fast zərf kimi də fast qalır."} ] },

     { h:"too və enough",
       t:["too + sifət = lazım olandan ÇOX (pis mənada): too hot (həddən artıq isti). too sifətdən ƏVVƏL gəlir.",
          "enough = kifayət qədər. enough sifətdən SONRA gəlir: old enough, big enough. Amma isimdən ƏVVƏL gəlir: enough money, enough time. not ... enough = kifayət qədər deyil."],
       tbl:[["too + sifət","too cold"],["sifət + enough","warm enough"],["enough + isim","enough money"]],
       ex:[["This tea is too hot. I can't drink it.","Bu çay çox istidir. İçə bilmirəm."],["He is not old enough to drive.","O, maşın sürmək üçün kifayət qədər böyük deyil."],["We have enough time.","Kifayət qədər vaxtımız var."],["The shoes are too small for me.","Ayaqqabılar mənə çox kiçikdir."]],
       no:"enough old / old too — səhvdir (old enough, too old)",
       q:[ {t:"mc", q:"I can't carry this bag. It's ___ .", opts:["too heavy","heavy too","enough heavy"], hint:"too sifətdən əvvəl gəlir."},
           {t:"mc", q:"She isn't ___ to watch this film.", opts:["old enough","enough old","too old enough"], hint:"enough sifətdən sonra gəlir."},
           {t:"mc", q:"Do we have ___ ?", opts:["enough chairs","chairs too","too enough chairs"], hint:"enough isimdən əvvəl gəlir."},
           {t:"gap", q:"The coffee is ___ sweet. I don't like it.", a:["too"], hint:"Həddən artıq → too."},
           {t:"gap", q:"Is the room big ___ for ten people?", a:["enough"], hint:"Sifətdən sonra → enough."} ] },

     { h:"-ed və -ing sifətlər (bored / boring)",
       t:["-ed ilə bitən sifət insanın HİSSİNİ bildirir: I am bored (darıxıram), I am tired (yorğunam), I am interested (maraqlanıram).",
          "-ing ilə bitən sifət hissi YARADAN şeyi təsvir edir: The film is boring (film darıxdırıcıdır), The job is tiring, The book is interesting. Qısa qayda: adam necə hiss edir → -ed; şey necədir → -ing."],
       tbl:[["hiss (-ed)","səbəb (-ing)"],["bored","boring"],["interested","interesting"],["tired","tiring"]],
       ex:[["I'm bored. Let's go out.","Darıxıram. Gəl çölə çıxaq."],["This lesson is very interesting.","Bu dərs çox maraqlıdır."],["She was tired after work.","İşdən sonra yorğun idi."],["The match was exciting.","Oyun həyəcanlı idi."]],
       no:"I am boring (darıxıram mənasında) — səhvdir (I am bored)",
       q:[ {t:"mc", q:"The film was very ___ . I almost slept.", opts:["boring","bored","bore"], hint:"Filmin özü necədir → -ing."},
           {t:"mc", q:"I'm ___ in history.", opts:["interested","interesting","interest"], hint:"İnsanın hissi → -ed."},
           {t:"mc", q:"After the long walk we were ___ .", opts:["tired","tiring","tire"], hint:"Biz necə hiss edirik → -ed."},
           {t:"gap", q:"The news was ___ (surprise). Nobody expected it.", a:["surprising"], hint:"Xəbərin özü necədir → -ing: surprising."},
           {t:"gap", q:"The children were ___ (excite) before the trip.", a:["excited"], hint:"Uşaqların hissi → -ed: excited."} ] }
   ],
   sum:["Sifət isimdən əvvəl və be-dən sonra gəlir: a big house, It is big.","Sifət cəmdə -s almır.","Zərf hərəkəti təsvir edir: slow → slowly; good → well; fast, hard dəyişmir.","too + sifət (çox); sifət + enough, enough + isim.","Hiss → -ed (bored), səbəb → -ing (boring)."] },

 { id:"T26", title:"Müqayisə: -er / more, the -est / the most, as … as", level:"A2",
   intro:"Bu dərsdə iki şeyi müqayisə etməyi (bigger, more expensive), birini hamıdan üstün göstərməyi (the biggest) və bərabərliyi (as big as) öyrənəcəksən.",
   steps:[
     { h:"Qısa sifətlər: -er + than",
       t:["İki şeyi müqayisə edəndə qısa sifətə (bir hecalı: big, old, cheap, fast) -er əlavə edirik. Sonra than (-dan / -dən) gəlir: Baku is bigger than Ganja (Bakı Gəncədən böyükdür).",
          "Yazılış: -e ilə bitirsə yalnız -r: nice → nicer. Bir sait + bir samit ilə bitirsə samit ikiləşir: big → bigger, hot → hotter. Samit + y ilə bitən iki hecalı sifətdə y → i: happy → happier, easy → easier."],
       tbl:[["old","older"],["nice","nicer"],["big","bigger"],["easy","easier"]],
       ex:[["My brother is older than me.","Qardaşım məndən böyükdür."],["This bag is cheaper than that one.","Bu çanta o birindən ucuzdur."],["Today is hotter than yesterday.","Bu gün dünəndən istidir."],["English is easier than Chinese.","İngilis dili Çin dilindən asandır."]],
       no:"more big / bigger that — səhvdir (bigger than)",
       q:[ {t:"mc", q:"A car is ___ a bike.", opts:["faster than","more fast than","faster that"], hint:"Qısa sifət: -er + than."},
           {t:"mc", q:"July is ___ than March.", opts:["hotter","hoter","more hot"], hint:"hot → hotter (samit ikiləşir)."},
           {t:"mc", q:"This test is ___ than the last one.", opts:["easier","easyer","more easy"], hint:"easy → easier (y → i)."},
           {t:"gap", q:"My flat is ___ (small) than your flat.", a:["smaller"], hint:"small → smaller."},
           {t:"gap", q:"Ali is taller ___ his father.", a:["than"], hint:"Müqayisədə -dan / -dən → than."} ] },

     { h:"Uzun sifətlər: more + than",
       t:["İki və daha çox hecalı sifətlər (y ilə bitənlərdən başqa) -er almır. Onların qabağına more (daha) qoyuruq: expensive → more expensive, beautiful → more beautiful, interesting → more interesting.",
          "Eyni sifətə həm more, həm -er birlikdə yazılmır. Azalma üçün less (daha az) işlənir: less expensive."],
       ex:[["A plane ticket is more expensive than a bus ticket.","Təyyarə bileti avtobus biletindən bahadır."],["This book is more interesting than that film.","Bu kitab o filmdən maraqlıdır."],["Health is more important than money.","Sağlamlıq puldan vacibdir."],["This phone is less expensive.","Bu telefon daha az bahadır."]],
       no:"expensiver / more cheaper — səhvdir (more expensive, cheaper)",
       q:[ {t:"mc", q:"Gold is ___ than silver.", opts:["more expensive","expensiver","more expensiver"], hint:"Uzun sifət → more + sifət."},
           {t:"mc", q:"This lesson is ___ than the first one.", opts:["more difficult","difficulter","most difficult"], hint:"difficult uzundur → more difficult."},
           {t:"mc", q:"My new job is ___ than my old job.", opts:["more interesting","interestinger","more interestinger"], hint:"more və -er birlikdə olmur."},
           {t:"gap", q:"Your idea is ___ useful than my idea.", a:["more"], hint:"useful iki hecalıdır → more useful."},
           {t:"gap", q:"Your dress is ___ (beautiful) than mine.", a:["more beautiful"], hint:"beautiful → more beautiful."} ] },

     { h:"Ən üstün: the -est / the most",
       t:["Bir şey qrupun HAMISINDAN üstün olanda qısa sifətə -est, uzun sifətə the most əlavə edirik. Hər ikisinin qabağında the olur: the biggest (ən böyük), the most beautiful (ən gözəl).",
          "Yazılış -er ilə eynidir: big → the biggest, happy → the happiest, nice → the nicest. Sonra çox vaxt in (yer, qrup) gəlir: the tallest in the class."],
       tbl:[["qısa","cheap → the cheapest"],["uzun","famous → the most famous"]],
       ex:[["Everest is the highest mountain in the world.","Everest dünyanın ən hündür dağıdır."],["He is the tallest boy in the class.","O, sinifdə ən hündür oğlandır."],["This is the most expensive hotel in the city.","Bu, şəhərin ən bahalı otelidir."],["It was the happiest day of my life.","Bu, həyatımın ən xoşbəxt günü idi."]],
       no:"the most big / most tallest — səhvdir (the biggest, the tallest)",
       q:[ {t:"mc", q:"She is ___ girl in our school.", opts:["the youngest","the most young","youngest than"], hint:"Qısa sifət → the + -est."},
           {t:"mc", q:"This is ___ film of the year.", opts:["the most popular","the popularest","the more popular"], hint:"Uzun sifət → the most."},
           {t:"mc", q:"It's ___ day of the year.", opts:["the hottest","the hotest","the most hot"], hint:"hot → the hottest."},
           {t:"gap", q:"This is the ___ (cheap) shop in town.", a:["cheapest"], hint:"cheap → the cheapest."},
           {t:"gap", q:"Baku is the ___ (big) city in Azerbaijan.", a:["biggest"], hint:"big → the biggest (samit ikiləşir)."} ] },

     { h:"Qaydasız: good, bad, far",
       t:["Üç sifət öz formalarını dəyişir, -er və more almır. Bunları əzbərlə: good → better → the best; bad → worse → the worst; far → further (və ya farther) → the furthest.",
          "better than = -dan yaxşı, worse than = -dan pis. more good, gooder kimi formalar yoxdur."],
       tbl:[["good","better","the best"],["bad","worse","the worst"],["far","further","the furthest"]],
       ex:[["Your English is better than mine.","Sənin ingiliscən mənimkindən yaxşıdır."],["This is the best pizza in town.","Bu, şəhərin ən yaxşı pizzasıdır."],["The weather is worse today.","Bu gün hava daha pisdir."],["It was the worst day of my life.","Həyatımın ən pis günü idi."]],
       no:"gooder / more good / the baddest — səhvdir (better, the worst)",
       q:[ {t:"mc", q:"I feel ___ today than yesterday.", opts:["better","gooder","more good"], hint:"good → better."},
           {t:"mc", q:"He is ___ player in the team.", opts:["the best","the goodest","the better"], hint:"good → the best."},
           {t:"mc", q:"My cold is ___ today. I feel terrible.", opts:["worse","badder","more bad"], hint:"bad → worse."},
           {t:"gap", q:"That was the ___ (bad) film I have seen.", a:["worst"], hint:"bad → the worst."},
           {t:"gap", q:"Her cooking is ___ (good) than my cooking.", a:["better"], hint:"good → better."} ] },

     { h:"Bərabər: as … as / not as … as",
       t:["İki şey BƏRABƏR olanda as + sifət + as işlədirik. Sifət burada dəyişmir (-er yox): Ali is as tall as Murad (Əli Murad qədər hündürdür).",
          "Bərabər olmayanda not as … as: Ganja is not as big as Baku (Gəncə Bakı qədər böyük deyil). Mənası: Bakı daha böyükdür."],
       ex:[["My bag is as heavy as your bag.","Mənim çantam sənin çantan qədər ağırdır."],["This film is not as good as the book.","Bu film kitab qədər yaxşı deyil."],["She is as old as me.","O, mənimlə yaşıddır."],["Tea isn't as expensive as coffee here.","Burada çay qəhvə qədər baha deyil."]],
       no:"as taller as / as big than — səhvdir (as tall as, as big as)",
       q:[ {t:"mc", q:"Tom is ___ his brother.", opts:["as tall as","as taller as","as tall than"], hint:"as + sifət (dəyişməz) + as."},
           {t:"mc", q:"The bus is not ___ the train.", opts:["as fast as","as faster as","fast as"], hint:"not as + sifət + as."},
           {t:"mc", q:"My room is as ___ as yours.", opts:["big","bigger","biggest"], hint:"as … as arasında sifət dəyişmir."},
           {t:"gap", q:"This test is as easy ___ the last one.", a:["as"], hint:"as … as."},
           {t:"gap", q:"Your car isn't ___ old as my car.", a:["as"], hint:"not as … as."} ] }
   ],
   sum:["Qısa sifət: -er than (bigger than), the -est (the biggest).","Uzun sifət: more … than, the most … .","good → better → the best; bad → worse → the worst.","more və -er birlikdə yazılmır.","Bərabər: as big as; bərabər deyil: not as big as."] },

 { id:"T27", title:"-ing yoxsa to + fel", level:"A2",
   intro:"Bəzi fellərdən sonra ikinci fel to + fel (to go), bəziləri isə -ing (going) ilə gəlir. Bu dərsdə hansı fellərdən sonra hansının gəldiyini siyahılarla öyrənəcəksən.",
   steps:[
     { h:"to + fel: want, need, decide …",
       t:["Bu fellərdən sonra ikinci fel to + felin əsas forması ilə gəlir: want, would like, need, decide, hope, plan, learn, try, forget, promise, agree. Məsələn: I want to sleep (yatmaq istəyirəm).",
          "Bu siyahını əzbərlə. Azərbaycancada «-maq / -mək» kimi düşün: istəyirəm getmək → want to go. to-dan sonra fel heç vaxt -s, -ed, -ing almır."],
       ex:[["I want to learn English.","İngilis dilini öyrənmək istəyirəm."],["She decided to buy a car.","O, maşın almağa qərar verdi."],["We need to go now.","İndi getməliyik."],["Don't forget to call me.","Mənə zəng etməyi unutma."],["I'd like to drink some water.","Bir az su içmək istərdim."]],
       no:"I want go / I want going — səhvdir (I want to go)",
       q:[ {t:"mc", q:"I want ___ a new phone.", opts:["to buy","buying","buy"], hint:"want → to + fel."},
           {t:"mc", q:"They decided ___ at home.", opts:["to stay","staying","stayed"], hint:"decide → to + fel."},
           {t:"mc", q:"She hopes ___ a doctor.", opts:["to become","becoming","becomes"], hint:"hope → to + fel."},
           {t:"gap", q:"We need ___ (leave) early tomorrow.", a:["to leave"], hint:"need → to leave."},
           {t:"gap", q:"I'd like ___ (visit) London.", a:["to visit"], hint:"would like → to + fel."} ] },

     { h:"-ing: enjoy, finish, mind …",
       t:["Bu fellərdən sonra ikinci fel -ing ilə gəlir: enjoy, finish, mind, stop, keep, practise, imagine, suggest, avoid. Məsələn: I enjoy reading (oxumaqdan zövq alıram).",
          "like, love, hate fellərindən sonra həm -ing, həm to + fel düzdür: I like swimming = I like to swim. Amma would like-dan sonra yalnız to + fel gəlir."],
       ex:[["I enjoy cooking.","Yemək bişirməkdən zövq alıram."],["He finished working at six.","O, saat altıda işi bitirdi."],["Do you mind waiting?","Gözləməyə etirazın var?"],["Stop talking, please.","Zəhmət olmasa, danışmağı dayandırın."],["She keeps calling me.","O, mənə zəng etməkdə davam edir."]],
       no:"I enjoy to read / I finished to eat — səhvdir (enjoy reading, finished eating)",
       q:[ {t:"mc", q:"I enjoy ___ to music.", opts:["listening","to listen","listen"], hint:"enjoy → -ing."},
           {t:"mc", q:"Have you finished ___ your homework?", opts:["doing","to do","do"], hint:"finish → -ing."},
           {t:"mc", q:"Would you mind ___ the window?", opts:["opening","to open","open"], hint:"mind → -ing."},
           {t:"gap", q:"He stopped ___ (smoke) last year.", a:["smoking"], hint:"stop → -ing: smoking."},
           {t:"gap", q:"Please keep ___ (practise).", a:["practising","practicing"], hint:"keep → -ing."} ] },

     { h:"Ön sözdən sonra -ing",
       t:["Ön sözdən (in, at, of, about, for, before, after, without) sonra fel gəlirsə, o fel HƏMİŞƏ -ing alır. Burada to + fel olmur.",
          "Çox işlənən birləşmələr: good at, interested in, tired of, thank you for, how about, before, after, without. Məsələn: I'm good at drawing."],
       ex:[["She is good at singing.","O, oxumağı yaxşı bacarır."],["Thank you for helping me.","Mənə kömək etdiyin üçün sağ ol."],["I'm interested in learning Spanish.","İspan dilini öyrənməklə maraqlanıram."],["Wash your hands before eating.","Yeməkdən əvvəl əllərini yu."],["He left without saying goodbye.","O, sağollaşmadan getdi."]],
       no:"good at swim / before to eat — səhvdir (good at swimming, before eating)",
       q:[ {t:"mc", q:"I'm tired of ___ .", opts:["waiting","to wait","wait"], hint:"of ön sözdür → -ing."},
           {t:"mc", q:"How about ___ to the cinema?", opts:["going","to go","go"], hint:"about ön sözdür → -ing."},
           {t:"mc", q:"He is good at ___ football.", opts:["playing","to play","play"], hint:"at ön sözdür → -ing."},
           {t:"gap", q:"Call me after ___ (finish) work.", a:["finishing"], hint:"after-dən sonra → -ing."},
           {t:"gap", q:"Thanks for ___ (come).", a:["coming"], hint:"for-dan sonra → -ing: coming."} ] },

     { h:"Məqsəd: to + fel (nə üçün?)",
       t:["«Nə üçün?» sualına cavab verəndə to + fel işlədirik. Azərbaycanca «-maq üçün» deməkdir: I went to the shop to buy bread (çörək almaq üçün mağazaya getdim).",
          "Burada for + fel yazılmır. for-dan sonra isim gəlir: I went to the shop for bread. Fel olanda isə to: to buy bread."],
       ex:[["I came here to see you.","Səni görmək üçün buraya gəldim."],["She studies hard to pass the exam.","İmtahandan keçmək üçün çox oxuyur."],["We went to the park to play.","Oynamaq üçün parka getdik."],["He called me to ask a question.","Sual vermək üçün mənə zəng etdi."]],
       no:"I went there for buy bread — səhvdir (to buy bread)",
       q:[ {t:"mc", q:"I went to the bank ___ money.", opts:["to get","for get","getting"], hint:"Nə üçün? → to + fel."},
           {t:"mc", q:"She called ___ hello.", opts:["to say","for saying","say"], hint:"Məqsəd → to + fel."},
           {t:"mc", q:"We went to the park ___ football.", opts:["to play","for play","play"], hint:"Məqsəd → to + fel."},
           {t:"gap", q:"He went to the shop ___ buy some milk.", a:["to"], hint:"Məqsəd → to + fel."},
           {t:"gap", q:"We study English ___ (find) a good job.", a:["to find"], hint:"Nə üçün? → to find."} ] }
   ],
   sum:["want, need, decide, hope, plan, would like, forget, learn, try → to + fel.","enjoy, finish, mind, stop, keep, practise, avoid → -ing.","like, love, hate → hər ikisi olur.","Ön sözdən sonra fel həmişə -ing alır.","Məqsəd (nə üçün?) → to + fel, for + fel yox."] },

 { id:"T28", title:"Ön sözlər: vaxt və yer (in / on / at)", level:"A2",
   intro:"Azərbaycancadakı «-da, -də» ingiliscədə üç sözə bölünür: in, on, at. Bu dərsdə əvvəl vaxt üçün, sonra yer üçün hansını seçəcəyini öyrənəcəksən.",
   steps:[
     { h:"Vaxt: at (saat və dəqiq an)",
       t:["at ən kiçik, dəqiq vaxt üçündür: saat (at 5 o'clock, at 7:30), at noon (günorta), at midnight (gecə yarısı).",
          "Bu sabit ifadələri əzbərlə: at night (gecə), at the weekend (həftəsonu), at the moment (hazırda), at Christmas, at lunchtime."],
       ex:[["The lesson starts at nine.","Dərs saat doqquzda başlayır."],["I sleep at midnight.","Gecə yarısı yatıram."],["I don't work at night.","Gecə işləmirəm."],["What do you do at the weekend?","Həftəsonu nə edirsən?"]],
       no:"in 8 o'clock / in night — səhvdir (at 8 o'clock, at night)",
       q:[ {t:"mc", q:"The film starts ___ 8 o'clock.", opts:["at","in","on"], hint:"Saat → at."},
           {t:"mc", q:"I can't sleep ___ night.", opts:["at","in","on"], hint:"night → at night."},
           {t:"mc", q:"We have lunch ___ 1 pm.", opts:["at","on","in"], hint:"Saat → at."},
           {t:"gap", q:"She is busy ___ the moment.", a:["at"], hint:"at the moment = hazırda."},
           {t:"gap", q:"I meet my friends ___ the weekend.", a:["at"], hint:"at the weekend."} ] },

     { h:"Vaxt: on (gün və tarix)",
       t:["on günlər və tarixlər üçündür: on Monday, on Friday, on 5 May, on my birthday, on New Year's Day.",
          "Gün + günün hissəsi birlikdə olanda da on: on Monday morning, on Sunday evening."],
       ex:[["I go to the gym on Monday.","Bazar ertəsi idmana gedirəm."],["My birthday is on 12 June.","Ad günüm 12 iyundadır."],["We met on Saturday evening.","Şənbə axşamı görüşdük."],["The shop is closed on Sundays.","Mağaza bazar günləri bağlıdır."]],
       no:"in Monday / at 5 May — səhvdir (on Monday, on 5 May)",
       q:[ {t:"mc", q:"I'll see you ___ Tuesday.", opts:["on","in","at"], hint:"Gün → on."},
           {t:"mc", q:"She was born ___ 3 March.", opts:["on","in","at"], hint:"Tarix → on."},
           {t:"mc", q:"The party is ___ 7 o'clock ___ Friday.", opts:["at / on","on / at","in / on"], hint:"Saat → at, gün → on."},
           {t:"gap", q:"What did you do ___ your birthday?", a:["on"], hint:"Xüsusi gün → on."},
           {t:"gap", q:"We play football ___ Sunday morning.", a:["on"], hint:"Gün + səhər → on."} ] },

     { h:"Vaxt: in (ay, il, fəsil, günün hissəsi)",
       t:["in böyük vaxt üçündür: aylar (in May), illər (in 2020), fəsillər (in summer), əsrlər. Günün hissələri də in ilə: in the morning, in the afternoon, in the evening (amma at night).",
          "next, last, this, every, today, tomorrow, yesterday sözlərindən əvvəl ön söz yazılmır: next week, last year, every day."],
       ex:[["It's very hot in July.","İyulda çox isti olur."],["I was born in 1995.","1995-ci ildə doğulmuşam."],["We go to the sea in summer.","Yayda dənizə gedirik."],["I drink coffee in the morning.","Səhər qəhvə içirəm."],["See you next week.","Gələn həftə görüşərik."]],
       no:"on 2020 / at summer / in next week — səhvdir (in 2020, in summer, next week)",
       q:[ {t:"mc", q:"It often snows ___ January.", opts:["in","on","at"], hint:"Ay → in."},
           {t:"mc", q:"I get up early ___ the morning.", opts:["in","on","at"], hint:"in the morning."},
           {t:"mc", q:"I'll call you ___ .", opts:["next week","in next week","on next week"], hint:"next-dən əvvəl ön söz yoxdur."},
           {t:"gap", q:"They moved to Baku ___ 2018.", a:["in"], hint:"İl → in."},
           {t:"gap", q:"I like walking ___ autumn.", a:["in"], hint:"Fəsil → in."} ] },

     { h:"Yer: in, on, at",
       t:["in = içində (qapalı yer, şəhər, ölkə): in the room, in the box, in Baku, in Azerbaijan. on = üstündə (səth): on the table, on the wall, on the floor.",
          "at = bir nöqtədə, adi fəaliyyət yerində: at home, at work, at school, at the bus stop, at the door. Sabit ifadələri əzbərlə: at home, at work, at school, in bed, on the bus / train."],
       tbl:[["in","in the bag, in London"],["on","on the table, on the wall"],["at","at home, at the station"]],
       ex:[["The keys are in my bag.","Açarlar çantamdadır."],["There is a picture on the wall.","Divarda şəkil var."],["I'm at home now.","İndi evdəyəm."],["She lives in Paris.","O, Parisdə yaşayır."],["Wait for me at the bus stop.","Məni avtobus dayanacağında gözlə."]],
       no:"in home / on Baku / at the box — səhvdir (at home, in Baku, in the box)",
       q:[ {t:"mc", q:"The milk is ___ the fridge.", opts:["in","on","at"], hint:"İçində → in."},
           {t:"mc", q:"Your phone is ___ the table.", opts:["on","in","at"], hint:"Üstündə → on."},
           {t:"mc", q:"My father is ___ work now.", opts:["at","in","on"], hint:"at work — sabit ifadə."},
           {t:"gap", q:"I live ___ Baku.", a:["in"], hint:"Şəhər → in."},
           {t:"gap", q:"The children are ___ school.", a:["at"], hint:"at school — sabit ifadə."} ] },

     { h:"Yer: next to, between, under, behind, in front of",
       t:["Bu ön sözlər yeri dəqiq göstərir: next to (yanında), between (arasında — iki şeyin), under (altında), behind (arxasında), in front of (qabağında), opposite (qarşısında).",
          "between iki şey arasında işlənir və and ilə gəlir: between the bank and the shop."],
       ex:[["The cat is under the bed.","Pişik çarpayının altındadır."],["Sit next to me.","Mənim yanımda otur."],["The car is behind the house.","Maşın evin arxasındadır."],["There's a tree in front of my window.","Pəncərəmin qabağında ağac var."],["The café is between the bank and the hotel.","Kafe bankla otelin arasındadır."]],
       q:[ {t:"mc", q:"The ball is ___ the table. (altında)", opts:["under","on","behind"], hint:"altında → under."},
           {t:"mc", q:"I sit ___ Ali in class. (yanında)", opts:["next to","between","under"], hint:"yanında → next to."},
           {t:"mc", q:"The shop is ___ the bank and the school.", opts:["between","next","behind of"], hint:"İki şeyin arasında → between … and."},
           {t:"gap", q:"The garden is ___ the house. (arxasında)", a:["behind"], hint:"arxasında → behind."},
           {t:"gap", q:"There is a bus stop in front ___ the hotel.", a:["of"], hint:"in front of."} ] }
   ],
   sum:["at — saat və dəqiq an: at 5, at night, at the weekend.","on — gün və tarix: on Monday, on 5 May.","in — ay, il, fəsil, the morning: in May, in 2020.","next / last / every / this-dən əvvəl ön söz yoxdur.","Yer: in (içində), on (üstündə), at (nöqtə: at home, at work).","next to, between … and, under, behind, in front of."] },

 { id:"T29", title:"Phrasal verbs", level:"B1",
   intro:"Phrasal verb = fel + kiçik söz (up, down, on, off, out …). Birlikdə yeni məna verirlər. Bu dərsdə ən çox işlənənləri və obyektin harada durduğunu öyrənəcəksən.",
   steps:[
     { h:"Phrasal verb nədir?",
       t:["Bəzi fellərdən sonra kiçik söz gəlir: up, down, in, out, on, off, back, away. Fel + bu söz birlikdə bir məna verir. get = almaq, amma get up = yataqdan qalxmaq.",
          "Ona görə hər birini ayrıca söz kimi öyrən. Zaman dəyişəndə yalnız fel dəyişir, kiçik söz eyni qalır: get up → got up, gets up, getting up."],
       ex:[["I get up at seven.","Saat yeddidə qalxıram."],["Sit down, please.","Zəhmət olmasa, oturun."],["She woke up early.","O, tez oyandı."],["Come in!","İçəri gəl!"],["Please stand up.","Zəhmət olmasa, ayağa qalxın."]],
       no:"I upped get — səhvdir (I got up)",
       q:[ {t:"mc", q:"I usually ___ at 7 am. (yataqdan qalxmaq)", opts:["get up","get down","get off"], hint:"get up = qalxmaq."},
           {t:"mc", q:"Yesterday she ___ at 6.", opts:["woke up","wake up","woked up"], hint:"Keçmiş: fel dəyişir (woke), up qalır."},
           {t:"mc", q:"Please ___ on this chair.", opts:["sit down","sit up","sit off"], hint:"sit down = oturmaq."},
           {t:"gap", q:"The door is open. Come ___ !", a:["in"], hint:"come in = içəri gəlmək."},
           {t:"gap", q:"He ___ up at 8 every day. (gets/get)", a:["gets"], hint:"he → gets up; up dəyişmir."} ] },

     { h:"Gündəlik: turn on / off, put on / take off",
       t:["turn on = yandırmaq (işığı, televizoru), turn off = söndürmək. put on = geyinmək, take off = soyunmaq (paltarı çıxarmaq).",
          "Bunların obyekti olur (nəyi?): turn on the light, put on your coat. Obyekt kiçik sözdən sonra da gələ bilər, arasında da: turn the light on = turn on the light."],
       ex:[["Turn off the TV, please.","Zəhmət olmasa, televizoru söndür."],["Can you turn on the light?","İşığı yandıra bilərsən?"],["Put on your jacket. It's cold.","Gödəkçəni gey. Soyuqdur."],["Take off your shoes, please.","Zəhmət olmasa, ayaqqabını çıxar."]],
       q:[ {t:"mc", q:"It's dark. ___ the light.", opts:["Turn on","Turn off","Take off"], hint:"Qaranlıqdır → yandır: turn on."},
           {t:"mc", q:"It's cold. ___ your coat.", opts:["Put on","Take off","Turn on"], hint:"Geyinmək → put on."},
           {t:"mc", q:"Please ___ your phone in the cinema.", opts:["turn off","turn on","put on"], hint:"Söndürmək → turn off."},
           {t:"gap", q:"It's hot. Take ___ your jumper.", a:["off"], hint:"take off = çıxarmaq."},
           {t:"gap", q:"Turn the radio ___ . I want to listen to music.", a:["on"], hint:"Musiqi dinləmək → turn on."} ] },

     { h:"Obyekt it / them olanda: arada durur",
       t:["Obyekt it, them, him, her, me kimi əvəzlik olanda o, MÜTLƏQ felin və kiçik sözün ARASINDA durur: turn it off, put them on.",
          "turn off it, put on them yazmaq səhvdir. Obyekt adi isim olanda (the TV) hər iki yer düzdür."],
       tbl:[["turn off the TV","düz"],["turn the TV off","düz"],["turn it off","düz"],["turn off it","səhv"]],
       ex:[["The TV is loud. Turn it off.","Televizor yüksəkdir. Onu söndür."],["These are your shoes. Put them on.","Bunlar sənin ayaqqabılarındır. Onları gey."],["Your hat? Take it off inside.","Papağın? İçəridə onu çıxar."],["Pick it up, please.","Zəhmət olmasa, onu götür."]],
       no:"Turn off it. / Put on them. — səhvdir (Turn it off. Put them on.)",
       q:[ {t:"mc", q:"The light is on. Please ___ .", opts:["turn it off","turn off it","it turn off"], hint:"it arada durur."},
           {t:"mc", q:"Here are your gloves. ___ .", opts:["Put them on","Put on them","Them put on"], hint:"them arada durur."},
           {t:"mc", q:"Which is correct?", opts:["Take it off.","Take off it.","Take off its."], hint:"Əvəzlik fel ilə kiçik sözün arasındadır."},
           {t:"gap", q:"Your coat is on the floor. Pick ___ up.", a:["it"], hint:"pick it up."},
           {t:"gap", q:"The TV is on, but nobody is watching. Turn it ___ .", a:["off"], hint:"Söndürmək → turn it off."} ] },

     { h:"Çox işlənənlər: look for, look after, give up, find out",
       t:["look for = axtarmaq; look after = qayğısına qalmaq, baxmaq (uşağa, heyvana); give up = tərgitmək, əl çəkmək; find out = öyrənmək (məlumat tapmaq).",
          "Bunlardan başqa: go out = çölə çıxmaq, come back = qayıtmaq, fill in = (forma) doldurmaq. look for və look after-da obyekt həmişə sonda gəlir: look for it."],
       ex:[["I'm looking for my keys.","Açarlarımı axtarıram."],["She looks after her little brother.","O, kiçik qardaşına baxır."],["He gave up smoking.","O, siqareti tərgitdi."],["I want to find out the truth.","Həqiqəti öyrənmək istəyirəm."],["When will you come back?","Nə vaxt qayıdacaqsan?"]],
       q:[ {t:"mc", q:"I can't find my phone. I'm ___ it.", opts:["looking for","looking after","giving up"], hint:"axtarmaq → look for."},
           {t:"mc", q:"Who ___ your dog when you travel?", opts:["looks after","looks for","finds out"], hint:"qayğısına qalmaq → look after."},
           {t:"mc", q:"Don't ___ ! You can do it.", opts:["give up","find out","look for"], hint:"əl çəkmək → give up."},
           {t:"gap", q:"Please fill ___ this form.", a:["in"], hint:"fill in = doldurmaq."},
           {t:"gap", q:"I'll go now and come ___ at 6.", a:["back"], hint:"come back = qayıtmaq."} ] }
   ],
   sum:["Phrasal verb = fel + up / down / on / off …, yeni məna verir.","Zaman dəyişəndə yalnız fel dəyişir: got up, woke up.","turn on / off, put on / take off.","Əvəzlik (it, them) arada durur: turn it off.","look for (axtarmaq), look after (baxmaq), give up (tərgitmək), find out (öyrənmək)."] },

 { id:"T30", title:"Passive (məchul növ)", level:"B1",
   intro:"Passive-də vacib olan işi kimin gördüyü yox, işin özüdür: The car was made in Japan (maşın Yaponiyada düzəldilib). Bu dərsdə indiki və keçmiş passive-i qurmağı öyrənəcəksən.",
   steps:[
     { h:"Passive nədir və necə qurulur?",
       t:["Adi (active) cümlədə işi görən subyektdir: They clean the room. Passive-də işin təsir etdiyi şey subyekt olur: The room is cleaned (otaq təmizlənir). Azərbaycancada «-ıl, -il, -ın, -in» şəkilçisinə bənzəyir.",
          "Qurulma: be + felin 3-cü forması (V3). Qaydalı fellərdə V3 = -ed (cleaned), qaydasızlarda öz forması (made, written, built). İşi kimin gördüyü bilinmir və ya vacib deyil."],
       tbl:[["active","They make cars here."],["passive","Cars are made here."]],
       ex:[["English is spoken here.","Burada ingiliscə danışılır."],["The room is cleaned every day.","Otaq hər gün təmizlənir."],["This house was built in 1990.","Bu ev 1990-cı ildə tikilib."],["The letters are sent by post.","Məktublar poçtla göndərilir."]],
       no:"The room is clean every day (təmizlənir mənasında) — səhvdir (is cleaned: V3 lazımdır)",
       q:[ {t:"mc", q:"Passive necə qurulur?", opts:["be + V3","have + V3","be + -ing"], hint:"Passive = be + 3-cü forma."},
           {t:"mc", q:"Rice ___ in Asia.", opts:["is grown","is grow","grows it"], hint:"be + V3: is grown."},
           {t:"mc", q:"The windows ___ every week.", opts:["are cleaned","are clean","cleaned are"], hint:"are + V3 (cleaned)."},
           {t:"gap", q:"Coffee is ___ (make) from beans.", a:["made"], hint:"make → V3: made."},
           {t:"gap", q:"These books are ___ (write) in English.", a:["written"], hint:"write → V3: written."} ] },

     { h:"İndiki passive: am / is / are + V3",
       t:["Adət, ümumi fakt üçün (Present Simple mənası): am / is / are + V3. Tək şey → is, cəm → are.",
          "İnkar: is not / isn't + V3, are not / aren't + V3. Sual: Is / Are + subyekt + V3? Məsələn: Is English spoken here?"],
       ex:[["Cheese is made from milk.","Pendir süddən hazırlanır."],["Cars are not allowed here.","Burada maşınlara icazə verilmir."],["Is breakfast included?","Səhər yeməyi daxildir?"],["Football is played all over the world.","Futbol bütün dünyada oynanılır."]],
       q:[ {t:"mc", q:"This song ___ on the radio every day.", opts:["is played","are played","is play"], hint:"Tək şey → is + V3."},
           {t:"mc", q:"Phones ___ in the exam.", opts:["aren't allowed","isn't allowed","don't allowed"], hint:"Cəm, inkar → aren't + V3."},
           {t:"mc", q:"___ French spoken in Canada?", opts:["Is","Does","Are"], hint:"Sual: Is + subyekt + V3?"},
           {t:"gap", q:"The shop ___ (be) opened at 9 every morning.", a:["is"], hint:"Tək şey, indiki → is."},
           {t:"gap", q:"Many cars are ___ (sell) in this shop.", a:["sold"], hint:"sell → V3: sold."} ] },

     { h:"Keçmiş passive: was / were + V3",
       t:["Keçmişdə olan iş üçün: was / were + V3. Tək şey → was, cəm → were.",
          "İnkar: wasn't / weren't + V3. Sual: Was / Were + subyekt + V3? Məsələn: When was this bridge built?"],
       ex:[["My phone was stolen yesterday.","Telefonum dünən oğurlandı."],["The pyramids were built long ago.","Piramidalar çox qədimdə tikilib."],["The letter wasn't sent.","Məktub göndərilmədi."],["Where were these photos taken?","Bu şəkillər harada çəkilib?"]],
       q:[ {t:"mc", q:"This book ___ in 1950.", opts:["was written","were written","was write"], hint:"Tək, keçmiş → was + V3."},
           {t:"mc", q:"The cakes ___ by my mother.", opts:["were made","was made","were make"], hint:"Cəm, keçmiş → were + V3."},
           {t:"mc", q:"When ___ the city founded?", opts:["was","did","were"], hint:"Tək, keçmiş sual → was."},
           {t:"gap", q:"Our car ___ (be) stolen last night.", a:["was"], hint:"Tək, keçmiş → was."},
           {t:"gap", q:"The windows were ___ (break) in the storm.", a:["broken"], hint:"break → V3: broken."} ] },

     { h:"by: işi kim gördü?",
       t:["İşi görəni demək istəsək, by işlədirik: The book was written by Nizami (kitab Nizami tərəfindən yazılıb). by = tərəfindən.",
          "Çox vaxt by lazım deyil, çünki iş görən bilinmir və ya vacib deyil: My bag was stolen (kimin oğurladığını bilmirəm)."],
       ex:[["This photo was taken by my sister.","Bu şəkil bacım tərəfindən çəkilib."],["The film was directed by a young woman.","Film gənc qadın tərəfindən çəkilib."],["The house was painted by my father.","Ev atam tərəfindən rənglənib."],["The window was broken.","Pəncərə sınıb."]],
       q:[ {t:"mc", q:"The Mona Lisa was painted ___ Leonardo.", opts:["by","from","with"], hint:"İşi görən → by."},
           {t:"mc", q:"The letter ___ by my teacher.", opts:["was written","wrote","was write"], hint:"was + V3 + by."},
           {t:"mc", q:"This dinner ___ by my brother.", opts:["was cooked","cooked was","is cook"], hint:"be + V3."},
           {t:"gap", q:"The team is trained ___ a famous coach.", a:["by"], hint:"tərəfindən → by."},
           {t:"gap", q:"The cake was ___ (eat) by the children.", a:["eaten"], hint:"eat → V3: eaten."} ] }
   ],
   sum:["Passive = be + V3; işin özü vacibdir.","İndiki: am / is / are + V3 (is made).","Keçmiş: was / were + V3 (was built).","İnkar: isn't / wasn't + V3; sual: Is / Was + subyekt + V3?","İşi görən → by (tərəfindən)."] },

 { id:"T31", title:"Relative clauses (who / which / that / where / whose)", level:"B1",
   intro:"Relative clause bir ismi izah edən cümlə hissəsidir: the man who lives here (burada yaşayan kişi). Bu dərsdə who, which, that, where və whose sözlərini ayrı-ayrı öyrənəcəksən.",
   steps:[
     { h:"who: insanlar üçün",
       t:["Bir insanı izah etmək üçün isimdən sonra who + cümlə yazırıq: the woman who works in the bank (bankda işləyən qadın). Azərbaycancada izah isimdən əvvəl gəlir, ingiliscədə isə SONRA.",
          "who özü subyektdir, ona görə ondan sonra ayrıca he / she yazılmır: the man who lives here, the man who he lives here yox."],
       ex:[["I have a friend who speaks five languages.","Beş dil bilən dostum var."],["The man who called you is my uncle.","Sənə zəng edən kişi əmimdir."],["She is the teacher who helped me.","O, mənə kömək edən müəllimdir."],["People who smoke are often ill.","Siqaret çəkən adamlar tez-tez xəstələnir."]],
       no:"the girl who she sings — səhvdir (the girl who sings)",
       q:[ {t:"mc", q:"The boy ___ lives next door is my friend.", opts:["who","which","where"], hint:"İnsan → who."},
           {t:"mc", q:"I know a woman ___ makes great cakes.", opts:["who","which","whose"], hint:"İnsan → who."},
           {t:"mc", q:"Which is correct?", opts:["The man who called me is here.","The man who he called me is here.","The man which called me is here."], hint:"who-dan sonra he yazılmır; insan → who."},
           {t:"gap", q:"Doctors are people ___ help sick people.", a:["who","that"], hint:"İnsan → who (that də olur)."},
           {t:"gap", q:"She's the girl who ___ (win) the race yesterday.", a:["won"], hint:"Keçmiş: win → won."} ] },

     { h:"which: əşya və heyvanlar üçün",
       t:["Əşyanı, heyvanı izah etmək üçün which işlədirik: the bus which goes to the airport (hava limanına gedən avtobus).",
          "İnsan üçün which işlənmir, əşya üçün who işlənmir. which-dən sonra da it yazılmır: the car which is red, the car which it is red yox."],
       ex:[["I bought a phone which has a big screen.","Böyük ekranı olan telefon aldım."],["This is the bus which goes to the centre.","Bu, mərkəzə gedən avtobusdur."],["Where is the book which was on the table?","Masanın üstündə olan kitab haradadır?"],["I have a cat which sleeps all day.","Bütün günü yatan pişiyim var."]],
       q:[ {t:"mc", q:"I like films ___ have happy endings.", opts:["which","who","where"], hint:"Əşya → which."},
           {t:"mc", q:"The man ___ fixed my car was very kind.", opts:["who","which","whose"], hint:"İnsan → who."},
           {t:"mc", q:"Where's the cake ___ was in the fridge?", opts:["which","who","where"], hint:"Əşya → which."},
           {t:"gap", q:"This is the train ___ goes to Ganja.", a:["which","that"], hint:"Əşya → which (that də olur)."},
           {t:"gap", q:"I have a dog ___ is very friendly.", a:["which","that"], hint:"Heyvan → which (that də olur)."} ] },

     { h:"that: insan və əşya üçün",
       t:["that həm insan, həm əşya üçün işlənə bilər. Danışıqda çox işlənir: the man that lives here = the man who lives here; the car that I bought = the car which I bought.",
          "Əgər that / who / which-dən sonra başqa subyekt gəlirsə (I, you, she …), onu buraxmaq olar: the car (that) I bought. Subyekt yoxdursa, buraxmaq olmaz: the man that lives here."],
       ex:[["The film that we watched was great.","İzlədiyimiz film əla idi."],["Is this the key that you lost?","Bu, itirdiyin açardır?"],["He's the man that sold me the car.","O, mənə maşını satan kişidir."],["The food (that) she cooked was delicious.","Onun bişirdiyi yemək dadlı idi."]],
       q:[ {t:"mc", q:"The bag ___ I bought is blue.", opts:["that","who","where"], hint:"Əşya → that (və ya which)."},
           {t:"mc", q:"She is the nurse ___ helped my mother.", opts:["that","which","where"], hint:"İnsan → that (və ya who)."},
           {t:"mc", q:"Which word can we use for people AND things?", opts:["that","which","who"], hint:"that hər ikisi üçündür."},
           {t:"gap", q:"Is this the song ___ you like?", a:["that","which"], hint:"Əşya → that / which."},
           {t:"gap", q:"I met a girl ___ knows your sister.", a:["that","who"], hint:"İnsan → that / who."} ] },

     { h:"where: yer üçün",
       t:["Yeri izah edəndə where işlədirik: the town where I was born (doğulduğum şəhər), the café where we met (görüşdüyümüz kafe).",
          "where-dən sonra tam cümlə gəlir (subyekt + fel): where I live, where she works."],
       ex:[["This is the house where I grew up.","Bu, böyüdüyüm evdir."],["Do you know a shop where I can buy shoes?","Ayaqqabı ala biləcəyim mağaza bilirsən?"],["The hotel where we stayed was nice.","Qaldığımız otel gözəl idi."],["That's the school where my son studies.","O, oğlumun oxuduğu məktəbdir."]],
       q:[ {t:"mc", q:"This is the city ___ I was born.", opts:["where","which","who"], hint:"Yer + subyekt + fel → where."},
           {t:"mc", q:"The restaurant ___ we ate was expensive.", opts:["where","who","whose"], hint:"Yer → where."},
           {t:"mc", q:"My uncle is the man ___ lives in London.", opts:["who","where","which"], hint:"İnsan → who."},
           {t:"gap", q:"Is there a park ___ we can play football?", a:["where"], hint:"Yer → where."},
           {t:"gap", q:"I visited the village ___ my father grew up.", a:["where"], hint:"Yer → where."} ] },

     { h:"whose: kimin?",
       t:["whose yiyəlik bildirir (onun …-ı): the man whose car is red (maşını qırmızı olan kişi). whose-dan sonra həmişə isim gəlir.",
          "whose = his / her / their yerinə işlənir. the woman whose son is a doctor = oğlu həkim olan qadın."],
       ex:[["I have a friend whose father is a pilot.","Atası pilot olan dostum var."],["That's the girl whose bag was stolen.","Bu, çantası oğurlanan qızdır."],["The boy whose dog is lost is crying.","İti itən oğlan ağlayır."],["He's the man whose house is near the sea.","O, evi dəniz kənarında olan kişidir."]],
       q:[ {t:"mc", q:"She's the woman ___ husband is a doctor.", opts:["whose","who","which"], hint:"onun əri → whose + isim."},
           {t:"mc", q:"I know a boy ___ sister is a singer.", opts:["whose","who","where"], hint:"Yiyəlik → whose."},
           {t:"mc", q:"The man ___ works here is my uncle.", opts:["who","whose","where"], hint:"Burada yiyəlik yoxdur, insan → who."},
           {t:"gap", q:"That's the student ___ phone was broken.", a:["whose"], hint:"onun telefonu → whose."},
           {t:"gap", q:"We met a family ___ house was very big.", a:["whose"], hint:"onların evi → whose."} ] }
   ],
   sum:["who — insanlar; which — əşya və heyvanlar; that — hər ikisi.","İzah isimdən SONRA gəlir: the man who lives here.","who / which-dən sonra he / it təkrar yazılmır.","where — yer: the house where I live.","whose + isim — yiyəlik: the man whose car is red."] },

 { id:"T32", title:"Bağlayıcılar (because, so, although, however, despite …)", level:"B1",
   intro:"Bağlayıcılar iki fikri birləşdirir. Bu dərsdə and / but / or, səbəb (because), nəticə (so) və ziddiyyət (although, however, despite) sözlərini ayrı-ayrı öyrənəcəksən.",
   steps:[
     { h:"and, but, or",
       t:["and = və (iki fikri əlavə edir). but = amma (ikinci fikir birinciyə ziddir). or = yoxsa / və ya (seçim).",
          "Bu sözlər iki cümlənin arasında durur: I like tea, but I don't like coffee."],
       ex:[["I have a brother and a sister.","Bir qardaşım və bir bacım var."],["She is tired, but she is happy.","O, yorğundur, amma xoşbəxtdir."],["Do you want tea or coffee?","Çay istəyirsən, yoxsa qəhvə?"],["I called him, but he didn't answer.","Ona zəng etdim, amma cavab vermədi."]],
       q:[ {t:"mc", q:"I like apples ___ bananas.", opts:["and","but","or"], hint:"Əlavə → and."},
           {t:"mc", q:"He is rich, ___ he isn't happy.", opts:["but","and","or"], hint:"Ziddiyyət → but."},
           {t:"mc", q:"Is your car red ___ blue?", opts:["or","and","but"], hint:"Seçim → or."},
           {t:"gap", q:"I wanted to go, ___ I was ill.", a:["but"], hint:"Ziddiyyət → but."},
           {t:"gap", q:"We can go by bus ___ by taxi.", a:["or"], hint:"Seçim → or."} ] },

     { h:"because: səbəb",
       t:["because = çünki, ona görə ki. Səbəbi bildirir və SƏBƏBİN qabağında durur: I stayed at home because I was ill (xəstə olduğum üçün evdə qaldım).",
          "because-dan sonra tam cümlə gəlir (subyekt + fel). İsim gəlirsə, because of işlənir: because of the rain (yağışa görə)."],
       ex:[["I'm hungry because I didn't have breakfast.","Acam, çünki səhər yeməyi yemədim."],["She is learning English because she wants a new job.","İngilis dili öyrənir, çünki yeni iş istəyir."],["The flight was late because of the snow.","Qara görə uçuş gecikdi."],["We didn't go out because it was cold.","Soyuq olduğu üçün çölə çıxmadıq."]],
       q:[ {t:"mc", q:"I went to bed early ___ I was tired.", opts:["because","but","or"], hint:"Səbəb → because."},
           {t:"mc", q:"The game stopped ___ the rain.", opts:["because of","because","but"], hint:"Sonra isim (the rain) → because of."},
           {t:"mc", q:"She is happy ___ she passed the exam.", opts:["because","or","because of"], hint:"Sonra cümlə gəlir → because."},
           {t:"gap", q:"I'm late ___ I missed the bus.", a:["because"], hint:"Səbəb + cümlə → because."},
           {t:"gap", q:"We stayed inside because ___ the storm.", a:["of"], hint:"because of + isim."} ] },

     { h:"so: nəticə",
       t:["so = ona görə də, buna görə. NƏTİCƏNİN qabağında durur: I was ill, so I stayed at home (xəstə idim, ona görə də evdə qaldım).",
          "because ilə müqayisə et: because-dan sonra səbəb, so-dan sonra nəticə gəlir. Eyni fikir: I was tired, so I slept = I slept because I was tired."],
       ex:[["It was raining, so we took a taxi.","Yağış yağırdı, ona görə taksi tutduq."],["I was hungry, so I made a sandwich.","Acıqmışdım, ona görə sendviç düzəltdim."],["The shop was closed, so we went home.","Mağaza bağlı idi, ona görə evə getdik."],["He is ill, so he can't come.","O, xəstədir, ona görə gələ bilmir."]],
       q:[ {t:"mc", q:"It was cold, ___ I put on a jacket.", opts:["so","because","or"], hint:"Nəticə → so."},
           {t:"mc", q:"I put on a jacket ___ it was cold.", opts:["because","so","and so"], hint:"Səbəb → because."},
           {t:"mc", q:"She didn't study, ___ she failed the test.", opts:["so","because","because of"], hint:"Nəticə → so."},
           {t:"gap", q:"The bus didn't come, ___ I walked.", a:["so"], hint:"Nəticə → so."},
           {t:"gap", q:"I walked ___ the bus didn't come.", a:["because"], hint:"Səbəb → because."} ] },

     { h:"although və however: ziddiyyət",
       t:["although = baxmayaraq ki. Tam cümlədən əvvəl gəlir: Although it was cold, we went to the beach (soyuq olmasına baxmayaraq, çimərliyə getdik). Bir cümlədə although və but birlikdə işlənmir.",
          "however = lakin, ancaq. Yeni cümlənin əvvəlində gəlir, ondan sonra vergül qoyulur: It was cold. However, we went to the beach."],
       ex:[["Although he is old, he runs every day.","Yaşlı olmasına baxmayaraq, hər gün qaçır."],["I went to work although I was ill.","Xəstə olmağıma baxmayaraq işə getdim."],["The hotel was nice. However, it was expensive.","Otel gözəl idi. Lakin baha idi."],["I like my job. However, the salary is low.","İşimi sevirəm. Ancaq maaş azdır."]],
       no:"Although it was cold, but we went out. — səhvdir (although və but birlikdə olmur)",
       q:[ {t:"mc", q:"___ it was late, they kept working.", opts:["Although","However","So"], hint:"Cümlənin əvvəlində, vergülsüz bağlayır → Although."},
           {t:"mc", q:"The film was long. ___ , it was interesting.", opts:["However","Although","Because"], hint:"Yeni cümlə + vergül → However."},
           {t:"mc", q:"Although she was tired, ___ .", opts:["she finished the work","but she finished the work","so she finished the work"], hint:"although ilə but / so birlikdə olmur."},
           {t:"gap", q:"I passed the test ___ I didn't study much.", a:["although","though"], hint:"baxmayaraq ki → although."},
           {t:"gap", q:"The food was good. ___ , the service was slow.", a:["however"], hint:"Yeni cümlə, ziddiyyət → However."} ] },

     { h:"despite / in spite of: + isim və ya -ing",
       t:["despite və in spite of də «baxmayaraq» deməkdir, amma onlardan sonra cümlə YOX, isim və ya -ing gəlir: despite the rain (yağışa baxmayaraq), in spite of being tired (yorğun olmasına baxmayaraq).",
          "Qısa qayda: although + cümlə (although it rained); despite + isim / -ing (despite the rain). despite of yazılmır."],
       tbl:[["although","+ cümlə: although it rained"],["despite","+ isim: despite the rain"],["in spite of","+ -ing: in spite of being ill"]],
       ex:[["We went out despite the rain.","Yağışa baxmayaraq çölə çıxdıq."],["Despite being tired, she finished the work.","Yorğun olmasına baxmayaraq, işi bitirdi."],["In spite of the traffic, we arrived on time.","Tıxaca baxmayaraq, vaxtında çatdıq."],["He played in spite of his bad leg.","Ayağı ağrımasına baxmayaraq oynadı."]],
       no:"despite of the rain / despite it rained — səhvdir (despite the rain, although it rained)",
       q:[ {t:"mc", q:"We played tennis ___ the rain.", opts:["despite","although","however"], hint:"Sonra isim → despite."},
           {t:"mc", q:"___ it was raining, we played tennis.", opts:["Although","Despite","In spite of"], hint:"Sonra cümlə → Although."},
           {t:"mc", q:"In spite of ___ ill, he came to work.", opts:["being","he was","be"], hint:"in spite of + -ing."},
           {t:"gap", q:"She smiled ___ the bad news.", a:["despite"], hint:"İsim → despite (və ya in spite of)."},
           {t:"gap", q:"In spite ___ the cold, the children played outside.", a:["of"], hint:"in spite of."} ] }
   ],
   sum:["and (və), but (amma), or (yoxsa).","because + cümlə (səbəb); because of + isim.","so → nəticə: I was ill, so I stayed home.","although + cümlə; however + vergül, yeni cümlənin əvvəlində.","despite / in spite of + isim və ya -ing; despite of yoxdur."] },

 { id:"T33", title:"Conditional 0 və 1 (real şərt)", level:"B1",
   intro:"Bu dərsdə real şərtləri öyrənəcəksən: həmişə doğru olan faktlar (Conditional 0) və gələcəkdə ola biləcək işlər (Conditional 1).",
   steps:[
     { h:"Conditional 0: həmişə doğru olan fakt",
       t:["Bir şey olanda HƏMİŞƏ eyni nəticə olursa (fakt, qanun, adət), if + Present Simple, Present Simple işlədirik: If you heat water to 100 degrees, it boils.",
          "Burada if = when (nə vaxt ki) mənasındadır. Hər iki hissədə Present Simple olur, will yoxdur."],
       tbl:[["if + Present Simple","Present Simple"],["If you heat ice,","it melts."]],
       ex:[["If it rains, the streets get wet.","Yağış yağanda küçələr islanır."],["If I drink coffee at night, I can't sleep.","Gecə qəhvə içəndə yata bilmirəm."],["If you mix red and blue, you get purple.","Qırmızı ilə göyü qarışdıranda bənövşəyi alınır."],["Plants die if they don't get water.","Su almayanda bitkilər ölür."]],
       q:[ {t:"mc", q:"If you heat ice, it ___ .", opts:["melts","will melted","melting"], hint:"Fakt → Present Simple."},
           {t:"mc", q:"If I ___ too much, I feel sick.", opts:["eat","will eat","ate"], hint:"if hissəsi → Present Simple."},
           {t:"mc", q:"If babies are hungry, they ___ .", opts:["cry","cries","crying"], hint:"they → cry."},
           {t:"gap", q:"If you ___ (press) this button, the light comes on.", a:["press"], hint:"if + Present Simple: press."},
           {t:"gap", q:"Water ___ (freeze) if it is very cold.", a:["freezes"], hint:"Water (it) → freezes."} ] },

     { h:"Conditional 1: gələcəkdə ola bilən iş",
       t:["Gələcəkdə ehtimal olunan şərt və onun nəticəsi üçün: if + Present Simple, will + fel. If it rains tomorrow, I will stay at home (sabah yağış yağsa, evdə qalacağam).",
          "Nəticədə will (və ya won't = will not) + felin əsas forması. Bu real ehtimaldır: ola bilər."],
       tbl:[["if + Present Simple","will + fel"],["If you study,","you will pass."]],
       ex:[["If you study, you will pass the exam.","Oxusan, imtahandan keçəcəksən."],["If it's sunny, we'll go to the beach.","Hava günəşli olsa, çimərliyə gedəcəyik."],["If you don't hurry, you'll miss the bus.","Tələsməsən, avtobusa çatmayacaqsan."],["If I see him, I'll tell him.","Onu görsəm, ona deyərəm."]],
       q:[ {t:"mc", q:"If you call me, I ___ you.", opts:["will help","helped","helping"], hint:"Nəticə → will + fel."},
           {t:"mc", q:"If it snows, we ___ to school.", opts:["won't go","don't went","not go"], hint:"İnkar nəticə → won't + fel."},
           {t:"mc", q:"If she comes, I ___ happy.", opts:["will be","will am","be"], hint:"will + be."},
           {t:"gap", q:"If you eat this, you ___ be ill.", a:["will","'ll"], hint:"Nəticə → will."},
           {t:"gap", q:"If we leave now, we ___ (catch) the train.", a:["will catch","'ll catch"], hint:"will + catch."} ] },

     { h:"if hissəsində will YOXDUR",
       t:["Ən çox edilən səhv: if-dən sonra will yazmaq. Gələcək mənası olsa da, if hissəsində Present Simple gəlir: If it rains (yağsa), If it will rain yox.",
          "will yalnız nəticə hissəsindədir. he / she / it ilə if hissəsində -s unutma: If he comes, …"],
       ex:[["If he calls, I'll answer.","O, zəng etsə, cavab verərəm."],["If you are late, the teacher will be angry.","Geciksən, müəllim əsəbiləşəcək."],["If she has time, she'll visit us.","Vaxtı olsa, bizə gələcək."],["If I find your keys, I'll call you.","Açarlarını tapsam, sənə zəng edərəm."]],
       no:"If it will rain, I will stay home. — səhvdir (If it rains, …)",
       q:[ {t:"mc", q:"If he ___ late, we will start without him.", opts:["is","will be","be"], hint:"if hissəsində will yoxdur → is."},
           {t:"mc", q:"If you ___ me, I'll help you.", opts:["ask","will ask","asked"], hint:"if + Present Simple."},
           {t:"mc", q:"Which is correct?", opts:["If she calls, I'll tell her.","If she will call, I'll tell her.","If she call, I'll tell her."], hint:"if + Present Simple; she → calls."},
           {t:"gap", q:"If it ___ (rain) tomorrow, we'll stay at home.", a:["rains"], hint:"it → rains, will yox."},
           {t:"gap", q:"If my mum ___ (find) out, she'll be angry.", a:["finds"], hint:"my mum (she) → finds."} ] },

     { h:"Söz sırası, vergül və suallar",
       t:["if hissəsi əvvəl və ya sonra gələ bilər. if əvvəldədirsə, arada vergül qoyulur: If you hurry, you'll catch the bus. if sonradırsa, vergül lazım deyil: You'll catch the bus if you hurry.",
          "Sual: What will you do if …? / Will you come if …? unless = if not (əgər … -masa): Unless you hurry = If you don't hurry."],
       ex:[["I'll call you if I have time.","Vaxtım olsa, sənə zəng edərəm."],["What will you do if you lose your job?","İşini itirsən, nə edəcəksən?"],["Will you come if I invite you?","Səni dəvət etsəm, gələcəksən?"],["Unless you study, you won't pass.","Oxumasan, keçməyəcəksən."]],
       q:[ {t:"mc", q:"What will you do if it ___ ?", opts:["rains","will rain","rain"], hint:"if hissəsi → Present Simple; it → rains."},
           {t:"mc", q:"___ you help me if I ask?", opts:["Will","Do","Are"], hint:"Nəticə hissəsinin sualı → Will."},
           {t:"mc", q:"Unless you hurry, you ___ the bus.", opts:["will miss","miss will","missed"], hint:"Nəticə → will + fel."},
           {t:"gap", q:"I'll be happy ___ you come.", a:["if"], hint:"Şərt → if."},
           {t:"gap", q:"You won't pass ___ you study. (= if you don't study)", a:["unless"], hint:"if not → unless."} ] }
   ],
   sum:["Conditional 0 (fakt): if + Present Simple, Present Simple.","Conditional 1 (ola bilər): if + Present Simple, will + fel.","if hissəsində will yazılmır.","if əvvəldə → vergül; sonda → vergülsüz.","unless = if not."] },

 { id:"T34", title:"Conditional 2 (xəyali indi)", level:"B1",
   intro:"Bu dərsdə indi real olmayan, xəyali vəziyyətləri danışmağı öyrənəcəksən: If I had a car, I would drive to work (maşınım olsaydı, işə maşınla gedərdim).",
   steps:[
     { h:"Nə vaxt işlənir?",
       t:["Conditional 2 indi və ya gələcəkdə REAL OLMAYAN, xəyali və ya çox az ehtimallı vəziyyət üçündür. Azərbaycancada «-saydı, -ardı» kimidir: Pulum olsaydı, ev alardım.",
          "Keçmiş zaman forması işlənir, amma mənası keçmiş DEYİL, indidir. If I had money = indi pulum yoxdur, amma olsaydı …"],
       ex:[["If I had money, I would buy a house.","Pulum olsaydı, ev alardım."],["If I lived in London, I would speak English every day.","Londonda yaşasaydım, hər gün ingiliscə danışardım."],["If she knew the answer, she would tell us.","Cavabı bilsəydi, bizə deyərdi."],["If I won the lottery, I would travel.","Lotereya udsaydım, səyahət edərdim."]],
       q:[ {t:"mc", q:"If I had a car, I ___ to work.", opts:["would drive","will drive","drove"], hint:"Xəyali → would + fel."},
           {t:"mc", q:"If I ___ his number, I would call him.", opts:["knew","know","will know"], hint:"if hissəsi → keçmiş forma: knew."},
           {t:"mc", q:"If I had wings, I ___ .", opts:["would fly","will fly","flew"], hint:"Real deyil → would + fel."},
           {t:"gap", q:"If I ___ (have) time, I would help you.", a:["had"], hint:"have → had."},
           {t:"gap", q:"If he lived near here, I ___ visit him often.", a:["would","'d"], hint:"Nəticə → would."} ] },

     { h:"Quruluş: if + Past Simple, would + fel",
       t:["if hissəsində Past Simple (went, had, lived), nəticə hissəsində would + felin əsas forması (would go, would buy). Qısa forması: I'd, you'd, she'd.",
          "Əvvəlki dərsdəki kimi, if hissəsində would yazılmır: If I had, If I would have yox. would-dan sonra fel -s, -ed almır."],
       tbl:[["if + Past Simple","would + fel"],["If I had time,","I would read more."]],
       ex:[["If we had a garden, we would grow vegetables.","Bağımız olsaydı, tərəvəz becərərdik."],["If he studied more, he'd get better marks.","Daha çox oxusaydı, yaxşı qiymətlər alardı."],["If you asked her, she would help.","Ondan xahiş etsəydin, kömək edərdi."],["If they came, we'd be happy.","Onlar gəlsəydi, sevinərdik."]],
       no:"If I would have money … — səhvdir (If I had money …)",
       q:[ {t:"mc", q:"If I ___ rich, I would buy a boat.", opts:["was","would be","am"], hint:"if hissəsi → Past Simple."},
           {t:"mc", q:"If she spoke English, she ___ that job.", opts:["would get","would gets","will get"], hint:"would + əsas forma."},
           {t:"mc", q:"Which is correct?", opts:["If I had a dog, I'd walk it every day.","If I would have a dog, I'd walk it every day.","If I have a dog, I'd walked it every day."], hint:"if + Past Simple, would + fel."},
           {t:"gap", q:"If we ___ (live) by the sea, we would swim every day.", a:["lived"], hint:"live → lived."},
           {t:"gap", q:"If you ate less sugar, you would ___ (feel) better.", a:["feel"], hint:"would + əsas forma: feel."} ] },

     { h:"If I were you: məsləhət",
       t:["Conditional 2-də be felindən bütün şəxslər üçün were işlətmək olar: If I were, If he were, If she were. Danışıqda I / he / she ilə was da eşidilir, amma were daha düzgündür.",
          "If I were you, I would … = Mən sənin yerində olsaydım, … — məsləhət vermək üçün ən çox işlənən ifadədir."],
       ex:[["If I were you, I would see a doctor.","Sənin yerində olsaydım, həkimə gedərdim."],["If I were you, I wouldn't buy that car.","Sənin yerində olsaydım, o maşını almazdım."],["If she were here, she would help us.","O, burada olsaydı, bizə kömək edərdi."],["If it were cheaper, I would buy it.","Daha ucuz olsaydı, alardım."]],
       q:[ {t:"mc", q:"If I ___ you, I would study more.", opts:["were","am","will be"], hint:"If I were you."},
           {t:"mc", q:"If I were you, I ___ that.", opts:["wouldn't do","won't do","didn't do"], hint:"would not + fel → wouldn't do."},
           {t:"mc", q:"If he ___ taller, he would play basketball.", opts:["were","is","be"], hint:"Xəyali → were."},
           {t:"gap", q:"If I ___ you, I'd call her.", a:["were","was"], hint:"If I were you."},
           {t:"gap", q:"If I were you, I ___ go to bed early.", a:["would","'d"], hint:"Məsləhət → would."} ] },

     { h:"İnkar və suallar",
       t:["İnkar: if hissəsində didn't + fel (If I didn't work), nəticədə wouldn't + fel (I wouldn't go).",
          "Sual: What would you do if …? Would you … if …? Məsələn: What would you do if you won a million?"],
       ex:[["If I didn't have work, I would go with you.","İşim olmasaydı, səninlə gedərdim."],["I wouldn't live there if I had a choice.","Seçimim olsaydı, orada yaşamazdım."],["What would you do if you saw a ghost?","Kabus görsəydin, nə edərdin?"],["Would you help me if I asked?","Xahiş etsəydim, kömək edərdin?"]],
       q:[ {t:"mc", q:"What ___ you do if you were rich?", opts:["would","will","did"], hint:"Xəyali sual → would."},
           {t:"mc", q:"If I ___ tired, I would come to the party.", opts:["wasn't","won't be","am not"], hint:"if hissəsi inkar → Past Simple: wasn't / weren't."},
           {t:"mc", q:"I ___ there if I were you.", opts:["wouldn't go","won't go","didn't go"], hint:"Nəticə inkar → wouldn't + fel."},
           {t:"gap", q:"___ you travel more if you had more money?", a:["would"], hint:"Sual → Would …?"},
           {t:"gap", q:"If he ___ (not / smoke), he would be healthier.", a:["didn't smoke","did not smoke"], hint:"Past Simple inkar: didn't smoke."} ] }
   ],
   sum:["Conditional 2 = indi real olmayan, xəyali vəziyyət.","if + Past Simple, would + fel.","Keçmiş forma, amma məna indidir.","If I were you, I would … — məsləhət.","if hissəsində would yazılmır."] },

 { id:"T35", title:"Conditional 3 (xəyali keçmiş)", level:"B1",
   intro:"Bu dərsdə keçmişdə OLMAYAN bir şeyi xəyal etməyi öyrənəcəksən: If I had studied, I would have passed (oxusaydım, keçərdim — amma oxumadım).",
   steps:[
     { h:"Nə vaxt işlənir?",
       t:["Conditional 3 keçmiş haqqındadır. Keçmişdə bir şey olmayıb və biz onun olsaydı nə olacağını təsəvvür edirik. Çox vaxt peşmanlıq və ya tənqid bildirir.",
          "Keçmişi dəyişmək mümkün deyil, ona görə bu, tam xəyalidir. If I had known = bilmirdim; I would have helped = kömək etmədim."],
       ex:[["If I had known, I would have helped you.","Bilsəydim, sənə kömək edərdim."],["If she had studied, she would have passed.","Oxusaydı, keçərdi."],["If we had left earlier, we would have caught the train.","Tez çıxsaydıq, qatara çatardıq."],["If you had asked me, I would have said yes.","Məndən soruşsaydın, hə deyərdim."]],
       q:[ {t:"mc", q:"Conditional 3 nə haqqındadır?", opts:["keçmişdə olmayan iş","indiki xəyal","gələcək plan"], hint:"Conditional 3 = xəyali keçmiş."},
           {t:"mc", q:"If I had seen you, I ___ hello.", opts:["would have said","would say","will say"], hint:"Xəyali keçmiş → would have + V3."},
           {t:"mc", q:"If he ___ harder, he would have won.", opts:["had tried","tried","has tried"], hint:"if hissəsi → had + V3."},
           {t:"gap", q:"If I had known, I ___ have come.", a:["would"], hint:"would have + V3."},
           {t:"gap", q:"If she had ___ (ask), I would have helped.", a:["asked"], hint:"had + V3: asked."} ] },

     { h:"if hissəsi: had + V3",
       t:["if hissəsində Past Perfect işlənir: had + felin 3-cü forması (V3). Bütün şəxslər üçün had: If I had, If she had, If they had.",
          "Qaydalı fellərdə V3 = -ed (worked, asked), qaydasızlarda öz forması (gone, seen, known, taken). Qısa forma: If I'd known."],
       ex:[["If I had gone to bed early, I wouldn't have been tired.","Tez yatsaydım, yorğun olmazdım."],["If they had taken a taxi, they would have arrived on time.","Taksi tutsaydılar, vaxtında çatardılar."],["If you had told me, I would have come.","Mənə desəydin, gələrdim."],["If she'd seen the sign, she would have stopped.","Nişanı görsəydi, dayanardı."]],
       no:"If I would have known … / If I knew (keçmiş üçün) — səhvdir (If I had known)",
       q:[ {t:"mc", q:"If we ___ the map, we wouldn't have got lost.", opts:["had taken","took","would take"], hint:"had + V3."},
           {t:"mc", q:"If she ___ the news, she would have called.", opts:["had heard","heard","has heard"], hint:"had + V3 (heard)."},
           {t:"mc", q:"If they ___ earlier, they would have seen the start.", opts:["had come","had came","came"], hint:"come → V3: come."},
           {t:"gap", q:"If I had ___ (know) about the party, I would have gone.", a:["known"], hint:"know → V3: known."},
           {t:"gap", q:"If you ___ (study), you would have passed.", a:["had studied","'d studied"], hint:"had + studied."} ] },

     { h:"Nəticə: would have + V3",
       t:["Nəticə hissəsində would have + V3 işlənir: I would have gone, she would have won. Qısa forma: I'd have, she'd have.",
          "have burada heç vaxt has olmur: she would have, she would has yox. Danışıqda would've kimi eşidilir."],
       tbl:[["if + had + V3","would have + V3"],["If I had seen it,","I would have bought it."]],
       ex:[["If it hadn't rained, we would have played.","Yağış yağmasaydı, oynayardıq."],["If he had been careful, he would have seen the car.","Ehtiyatlı olsaydı, maşını görərdi."],["She would have won if she had trained more.","Daha çox məşq etsəydi, qalib gələrdi."],["We would have bought the house if it had been cheaper.","Ucuz olsaydı, evi alardıq."]],
       no:"she would has gone / I would have went — səhvdir (would have gone)",
       q:[ {t:"mc", q:"If you had called, I ___ .", opts:["would have answered","would answered","will have answered"], hint:"would have + V3."},
           {t:"mc", q:"She ___ the job if she had applied.", opts:["would have got","would has got","would got"], hint:"have heç vaxt has olmur."},
           {t:"mc", q:"If I had known, I would have ___ you.", opts:["told","tell","telled"], hint:"tell → V3: told."},
           {t:"gap", q:"If he had run, he would have ___ (catch) the bus.", a:["caught"], hint:"catch → V3: caught."},
           {t:"gap", q:"We would ___ won if we had played better.", a:["have"], hint:"would have + V3."} ] },

     { h:"İnkar və suallar",
       t:["İnkar: if hissəsində hadn't + V3 (If I hadn't gone), nəticədə wouldn't have + V3 (I wouldn't have met her).",
          "Sual: What would you have done if …? Would you have come if …?"],
       ex:[["If I hadn't gone to that party, I wouldn't have met my wife.","O qonaqlığa getməsəydim, həyat yoldaşımla tanış olmazdım."],["If you hadn't helped me, I would have failed.","Mənə kömək etməsəydin, uğursuz olardım."],["What would you have done if you had lost your passport?","Pasportunu itirsəydin, nə edərdin?"],["Would you have come if I had invited you?","Səni dəvət etsəydim, gələrdin?"]],
       q:[ {t:"mc", q:"If it ___ so cold, we would have gone out.", opts:["hadn't been","wasn't","wouldn't be"], hint:"if hissəsi inkar → hadn't + V3."},
           {t:"mc", q:"If I had seen the car, I ___ it.", opts:["wouldn't have hit","wouldn't hit","didn't hit"], hint:"wouldn't have + V3."},
           {t:"mc", q:"What would you ___ if you had missed the plane?", opts:["have done","did","done"], hint:"would have + V3."},
           {t:"gap", q:"If you ___ (not / forget) the keys, we wouldn't have waited.", a:["hadn't forgotten","had not forgotten"], hint:"hadn't + V3: forgotten."},
           {t:"gap", q:"___ you have gone if they had asked you?", a:["would"], hint:"Sual → Would … have + V3?"} ] }
   ],
   sum:["Conditional 3 = keçmişdə olmayan iş; çox vaxt peşmanlıq.","if + had + V3, would have + V3.","have heç vaxt has olmur: she would have gone.","İnkar: hadn't + V3, wouldn't have + V3.","if hissəsində would yazılmır."] },

 { id:"T36", title:"Reported speech (dolayı nitq)", level:"B1",
   intro:"Başqasının sözünü öz sözlərinlə ötürəndə reported speech işlənir: «I'm tired» → She said she was tired. Bu dərsdə zamanın necə dəyişdiyini, say / tell fərqini və sualları öyrənəcəksən.",
   steps:[
     { h:"said (that) + zaman bir addım geri",
       t:["Kiminsə sözünü ötürəndə said (dedi) işlədirik, sonra that (ki) gəlir. that-i buraxmaq olar. Azərbaycancada «dedi ki, …» kimidir.",
          "Sözlər keçmişdə deyilibsə, zaman bir addım geri gedir: Present Simple → Past Simple (am / is → was, like → liked), Present Continuous → Past Continuous (am working → was working)."],
       tbl:[["«I am happy.»","He said (that) he was happy."],["«I like tea.»","She said (that) she liked tea."],["«I'm working.»","He said he was working."]],
       ex:[["«I'm hungry.» → He said he was hungry.","«Acam.» → Ac olduğunu dedi."],["«I live in Baku.» → She said that she lived in Baku.","Bakıda yaşadığını dedi."],["«We are watching TV.» → They said they were watching TV.","Televizor izlədiklərini dedilər."],["«It's cold.» → He said it was cold.","Soyuq olduğunu dedi."]],
       q:[ {t:"mc", q:"«I am tired.» → She said she ___ tired.", opts:["was","is","were"], hint:"am → was."},
           {t:"mc", q:"«I like pizza.» → He said he ___ pizza.", opts:["liked","likes","like"], hint:"Present Simple → Past Simple."},
           {t:"mc", q:"«We are playing.» → They said they ___ playing.", opts:["were","are","was"], hint:"are → were."},
           {t:"gap", q:"«I work in a bank.» → He said he ___ (work) in a bank.", a:["worked"], hint:"work → worked."},
           {t:"gap", q:"«It is late.» → She said it ___ late.", a:["was"], hint:"is → was."} ] },

     { h:"say yoxsa tell?",
       t:["say-dan sonra adam yazmırıq: He said (that) … . Adamı demək istəsək, say to me deyirik, amma bu az işlənir.",
          "tell-dən sonra HƏMİŞƏ adam gəlir (kimə?): He told me (that) … , She told us … . Keçmiş formaları: say → said, tell → told."],
       tbl:[["say","He said (that) he was ill."],["tell + adam","He told me (that) he was ill."]],
       ex:[["She said she was busy.","Məşğul olduğunu dedi."],["She told me she was busy.","Mənə məşğul olduğunu dedi."],["He told us that he liked the film.","Bizə filmi bəyəndiyini dedi."],["They said they were happy.","Xoşbəxt olduqlarını dedilər."]],
       no:"He said me … / He told that … — səhvdir (He told me … / He said that …)",
       q:[ {t:"mc", q:"She ___ me she was ill.", opts:["told","said","says"], hint:"Sonra adam (me) → told."},
           {t:"mc", q:"He ___ that he was hungry.", opts:["said","told","tell"], hint:"Sonra adam yoxdur → said."},
           {t:"mc", q:"Which is correct?", opts:["They told us they were late.","They said us they were late.","They told they were late."], hint:"tell + adam; say + adamsız."},
           {t:"gap", q:"My teacher ___ me that I was good at English. (tell)", a:["told"], hint:"tell → told."},
           {t:"gap", q:"Ali ___ that he lived in Ganja. (say)", a:["said"], hint:"say → said."} ] },

     { h:"Əvəzliklər və sözlər dəyişir",
       t:["Başqasının sözünü ötürəndə əvəzlikləri DANIŞANA görə dəyişirik: Ali: «I am tired.» → Ali said HE was tired. Mary: «My car is old.» → Mary said HER car was old.",
          "Vaxt və yer sözləri də çox vaxt dəyişir: now → then, today → that day, tomorrow → the next day, here → there."],
       ex:[["Leyla: «I am cold.» → Leyla said she was cold.","Leyla üşüdüyünü dedi."],["Tom: «My sister is a nurse.» → Tom said his sister was a nurse.","Tom bacısının tibb bacısı olduğunu dedi."],["They: «We are busy now.» → They said they were busy then.","Onlar o vaxt məşğul olduqlarını dedilər."],["He: «I'm here.» → He said he was there.","O, orada olduğunu dedi."]],
       q:[ {t:"mc", q:"Murad: «I am happy.» → Murad said ___ was happy.", opts:["he","I","she"], hint:"I (Murad) → he."},
           {t:"mc", q:"Sara: «My bag is new.» → Sara said ___ bag was new.", opts:["her","my","his"], hint:"my (Sara) → her."},
           {t:"mc", q:"They: «We are tired.» → They said ___ were tired.", opts:["they","we","you"], hint:"we → they."},
           {t:"gap", q:"Ali: «I'm busy now.» → Ali said he was busy ___ .", a:["then"], hint:"now → then."},
           {t:"gap", q:"Nigar: «My phone is broken.» → Nigar said ___ phone was broken.", a:["her"], hint:"my → her."} ] },

     { h:"will → would, can → could",
       t:["Modal fellər də bir addım geri gedir: will → would, can → could. Sonrakı fel dəyişmir: «I will call» → He said he would call.",
          "Past Simple da bir addım geri gedə bilər (had + V3), amma danışıqda çox vaxt eyni qalır: «I saw it» → He said he saw it / had seen it."],
       tbl:[["will","would"],["can","could"],["won't","wouldn't"],["can't","couldn't"]],
       ex:[["«I will help you.» → She said she would help me.","Mənə kömək edəcəyini dedi."],["«I can swim.» → He said he could swim.","Üzə bildiyini dedi."],["«We won't be late.» → They said they wouldn't be late.","Gecikməyəcəklərini dedilər."],["«I can't come.» → She said she couldn't come.","Gələ bilməyəcəyini dedi."]],
       q:[ {t:"mc", q:"«I will call you.» → He said he ___ call me.", opts:["would","will","can"], hint:"will → would."},
           {t:"mc", q:"«I can drive.» → She said she ___ drive.", opts:["could","can","would"], hint:"can → could."},
           {t:"mc", q:"«I won't tell anyone.» → He said he ___ anyone.", opts:["wouldn't tell","won't tell","wouldn't told"], hint:"won't → wouldn't + fel."},
           {t:"gap", q:"«We can't come.» → They said they ___ come.", a:["couldn't","could not"], hint:"can't → couldn't."},
           {t:"gap", q:"«It will rain.» → He said it ___ rain.", a:["would"], hint:"will → would."} ] },

     { h:"Dolayı suallar: asked if / asked where",
       t:["Sualı ötürəndə asked (soruşdu) işlədirik. Dolayı sualda söz sırası adi cümlə kimidir (subyekt + fel), do / does / did işlənmir və sual işarəsi qoyulmur.",
          "Hə / yox sualı → asked if: «Are you hungry?» → She asked if I was hungry. Sual sözlü sual → asked + sual sözü: «Where do you live?» → He asked where I lived."],
       tbl:[["«Are you OK?»","He asked if I was OK."],["«Where do you work?»","She asked where I worked."]],
       ex:[["«Do you like coffee?» → She asked if I liked coffee.","Qəhvəni sevib-sevmədiyimi soruşdu."],["«Where is the station?» → He asked where the station was.","Stansiyanın harada olduğunu soruşdu."],["«What time is it?» → She asked what time it was.","Saatın neçə olduğunu soruşdu."],["«Can you help me?» → He asked if I could help him.","Ona kömək edə biləcəyimi soruşdu."]],
       no:"He asked where did I live. — səhvdir (He asked where I lived.)",
       q:[ {t:"mc", q:"«Are you tired?» → She asked ___ I was tired.", opts:["if","that","what"], hint:"Hə / yox sualı → asked if."},
           {t:"mc", q:"«Where do you live?» → He asked where ___ .", opts:["I lived","did I live","do I live"], hint:"Dolayı sual: subyekt + fel, did yoxdur."},
           {t:"mc", q:"«What is your name?» → She asked what my name ___ .", opts:["was","is","did"], hint:"is → was, söz sırası adi."},
           {t:"gap", q:"«Do you speak English?» → He asked ___ I spoke English.", a:["if","whether"], hint:"Hə / yox sualı → if."},
           {t:"gap", q:"«Where is the bank?» → She asked where the bank ___ .", a:["was"], hint:"is → was, sonda."} ] }
   ],
   sum:["said (that) + zaman bir addım geri: is → was, like → liked.","say + adamsız; tell + adam (told me).","Əvəzliklər danışana görə dəyişir: I → he / she, my → his / her.","will → would, can → could.","Dolayı sual: asked if … / asked where + subyekt + fel, do / did yox."] }
);
